-- =============================================================================
-- Seed: TradeEntities from 'ATV & UTV Parts.xls' (China suppliers)
-- Generated: 2026-04-24 23:35:24
-- Rows: 359
-- =============================================================================
SET NOCOUNT ON;
BEGIN TRANSACTION;

DECLARE @Now datetime2 = SYSUTCDATETIME();

-- Staging table holds a deterministic Id per source row so child phone
-- numbers can reference the parent without an OUTPUT-into round trip.
DECLARE @Stage TABLE (
    Id uniqueidentifier NOT NULL,
    LegalName nvarchar(500) NOT NULL,
    TradeName nvarchar(500) NULL,
    Region nvarchar(200) NULL,
    City nvarchar(200) NULL,
    ProductCategories nvarchar(1000) NULL,
    ExternalRegistryLinks nvarchar(4000) NULL,
    Mobile nvarchar(50) NULL,
    Tel nvarchar(50) NULL,
    Fax nvarchar(50) NULL
);


-- Insert parent TradeEntities (skip duplicates by LegalName)
    Id, LegalName, TradeName, EntityType, Country, Region, City,
    ProductCategories, VerificationStatus, VerificationScore, ExternalRegistryLinks,
    TotalReviewCount, InfoReviewCount, WarningReviewCount, CriticalReviewCount,
    LastReviewDate, ListedDate, CreatedAt, CreatedBy, UpdatedAt, UpdatedBy
)
SELECT
    s.Id, s.LegalName, s.TradeName, N'Supplier', N'China', s.Region, s.City,
    s.ProductCategories, N'Unverified', 0, s.ExternalRegistryLinks,
    0, 0, 0, 0, NULL, @Now, @Now, NULL, NULL, NULL
FROM @Stage s
WHERE NOT EXISTS (SELECT 1 FROM dbo.TradeEntities te WHERE te.LegalName = s.LegalName);

-- Insert phone numbers (one row per non-empty Mobile/Tel/Fax). Mobile is primary.
SELECT NEWID(), s.Id, s.Mobile, 1, @Now, NULL FROM @Stage s WHERE s.Mobile IS NOT NULL
UNION ALL
SELECT NEWID(), s.Id, s.Tel,    0, @Now, NULL FROM @Stage s WHERE s.Tel    IS NOT NULL
UNION ALL
SELECT NEWID(), s.Id, s.Fax,    0, @Now, NULL FROM @Stage s WHERE s.Fax    IS NOT NULL;

DECLARE @Inserted int = (SELECT COUNT(*) FROM @Stage);
PRINT CONCAT('Inserted ', @Inserted, ' staged rows.');
COMMIT TRANSACTION;

